@admin_bp.route('/test-nac-api-connection', methods=['GET'])
def test_nac_api_connection():
    """
    Test connection to NaC API (SCM)
    ---
    tags:
      - Admin
    summary: Test NaC API connectivity
    description: Tests the connection to NaC API SCM endpoint using configured credentials
    responses:
      200:
        description: Connection test result
        schema:
          type: object
          properties:
            status:
              type: string
              enum: [success, error]
              example: success
            message:
              type: string
              example: "Successfully connected to NaC API"
            scm_api_url:
              type: string
              example: "https://api.github.com"
            scm_provider:
              type: string
              example: "github"
      500:
        description: Connection test failed
        schema:
          type: object
          properties:
            status:
              type: string
              example: error
            message:
              type: string
              example: "Connection test failed: Connection timeout"
    """
    try:
        # Configuration file path
        yaml_dir = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(__file__))), 'yaml')
        config_path = os.path.join(yaml_dir, 'config.yaml')

        # Check if config file exists
        if not os.path.exists(config_path):
            return jsonify({
                'status': 'error',
                'message': 'No configuration found. Please configure NaC API settings first.'
            }), 500

        # Read YAML file
        with open(config_path, 'r') as f:
            config_data = yaml.safe_load(f) or {}

        nac_config = config_data.get('nac', {})
        api_url = nac_config.get('api_url', '')
        scm_api_url = nac_config.get('scm_api_url', '')
        scm_provider = nac_config.get('scm_provider', '')
        api_key = nac_config.get('api_key', '')
        repository_url = nac_config.get('repository_url', '')
        data_sources = nac_config.get('data_sources_dir', '')

        if not scm_api_url:
            return jsonify({
                'status': 'error',
                'message': 'SCM API URL is not configured'
            }), 500

        if not scm_provider:
            return jsonify({
                'status': 'error',
                'message': 'SCM Provider is not configured'
            }), 500

        # Test connection to SCM API
        headers = {
            'Content-Type': 'application/json'
        }

        # Add authentication header if API key is configured
        if api_key:
            # Different SCM providers use different auth methods
            if scm_provider == 'github':
                headers['Authorization'] = f'passthrough {api_key}'
                headers['x-git-config'] = f'api_url={scm_api_url};repository={repository_url};data_sources={data_sources};type=github'
            elif scm_provider == 'gitlab':
                headers['PRIVATE-TOKEN'] = api_key
            elif scm_provider in ['bitbucket_cloud', 'bitbucket_local']:
                headers['Authorization'] = f'Bearer {api_key}'
            elif scm_provider == 'azure_devops':
                headers['Authorization'] = f'Basic {api_key}'


        # This is the endpoint that we will utilize. This will return the complete 
        # data model. So we might need to revisit to just pull a small part of hte model.
        test_endpoint = '/api/v1/operations/read' 

        response = requests.get(
            f"{api_url}{test_endpoint}",
            headers=headers,
            timeout=10,
            verify=False
        )

        if response.status_code in [200, 201]:
            return jsonify({
                'status': 'success',
                'message': f'Successfully connected to NaC API ({scm_provider})',
                'scm_api_url': scm_api_url,
                'scm_provider': scm_provider,
                'size_of_data_model': len(response.content)
            })
        else:
            return jsonify({
                'status': 'error',
                'message': f'NaC API returned status code {response.status_code}'
            }), 500

    except requests.exceptions.Timeout:
        return jsonify({
            'status': 'error',
            'message': 'Connection test failed: Request timeout (10s)'
        }), 500
    except requests.exceptions.ConnectionError:
        return jsonify({
            'status': 'error',
            'message': 'Connection test failed: Unable to connect to NaC API'
        }), 500
    except requests.exceptions.RequestException as e:
        return jsonify({
            'status': 'error',
            'message': f'Connection test failed: {str(e)}'
        }), 500
    except Exception as e:
        return jsonify({
            'status': 'error',
            'message': f'Connection test failed: {str(e)}'
        }), 500

